function parseEmbedding(e){try{const t=JSON.parse(e);return Array.isArray(t)?t:[]}catch{return[]}}function encodeMemoryEmbedding(e){const t=new Uint8Array(e.length*8);const n=new DataView(t.buffer);for(let t=0;t<e.length;t+=1){const r=e[t];if(typeof r!==`number`||!Number.isFinite(r))throw new Error(`Memory embeddings require finite numeric coordinates`);n.setFloat64(t*8,r,true)}return t}function decodeMemoryEmbedding(e){if(e.byteLength%8!==0)return[];const t=new DataView(e.buffer,e.byteOffset,e.byteLength);const n=[];for(let r=0;r<e.byteLength;r+=8){const e=t.getFloat64(r,true);if(!Number.isFinite(e))return[];n.push(e)}return n}export{encodeMemoryEmbedding as n,parseEmbedding as r,decodeMemoryEmbedding as t};